item.command:
/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, a=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));
  always #5 clk = ~clk;

  task send(input bit v);
    begin
      a = v;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b shift=%09b match=%0b", $time, v, dut.a_tem, match);
    end
  endtask

  initial begin
    repeat(2) @(posedge clk);
    rst_n = 1;
    // pattern 011000110 should match on final bit
    send(0); send(1); send(1); send(0); send(0); send(0); send(1); send(1); send(0);
    // extra cycles
    send(0); send(0);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

